-- Expand Casa & Lar vocabulary without replacing existing account keywords.
-- The classifier rules remain source-agnostic; this catalog supports routing and search.
UPDATE categories AS c
SET keywords = (
  SELECT COALESCE(jsonb_agg(to_jsonb(term) ORDER BY term), '[]'::jsonb)
  FROM (
    SELECT DISTINCT lower(btrim(value)) AS term
    FROM jsonb_array_elements_text(COALESCE(c.keywords, '[]'::jsonb)) AS existing(value)
    WHERE btrim(value) <> ''
    UNION
    SELECT lower(btrim(value)) AS term
    FROM unnest(ARRAY['jogo americano','sousplat','toalha de mesa','trilho de mesa','guardanapo de tecido','porta guardanapo','descanso de panela','aparelho de jantar','jogo de jantar','faqueiro','jogo de talheres','taça de vinho','taças','jarra de mesa','bandeja de servir','boleira','prato de sobremesa','prato raso','prato fundo','travessa de servir','petisqueira','saladeira','manteigueira','açucareiro','leiteira de mesa','processador de alimentos','multiprocessador','máquina de café','moedor de café','sanduicheira','grill elétrico','torradeira','chaleira elétrica','panela elétrica','panela de arroz','panela de pressão elétrica','pipoqueira elétrica','espremedor de frutas','máquina de waffle','máquina de crepe','forno elétrico de bancada','caixa organizadora','caixas organizadoras','cesto organizador','cestos organizadores','organizador de gaveta','organizador de armário','organizador de cozinha','organizador de geladeira','organizador de despensa','organizador de banheiro','organizador de lavanderia','organizador de brinquedos','divisor de gaveta','pote para mantimentos','porta mantimentos','gancho adesivo','gancho de parede','suporte multiuso','baú organizador','gaveteiro','câmera wi-fi residencial','câmera de segurança residencial','câmera ip residencial','vídeo porteiro','interfone residencial','alarme residencial','fechadura digital','fechadura inteligente','fechadura eletrônica residencial','sensor de abertura','sensor de movimento residencial','detector de fumaça','detector de gás','tomada wi-fi','interruptor wi-fi','relé inteligente','controle infravermelho smart','central de automação residencial','campainha inteligente','olho mágico digital','ar-condicionado portátil','ar condicionado portátil','ventilador de teto','ventilador de coluna','climatizador evaporativo','umidificador ultrassônico','desumidificador de ar','purificador de ar hepa','adega climatizada','frigobar','cervejeira','máquina de gelo','cortina rolô','cortina romana','persiana rolô','papel de parede','adesivo decorativo','quadro decorativo','escultura decorativa','centro de mesa','vaso de cerâmica','cachepô decorativo','jogo de cama casal','jogo de cama queen','jogo de cama king','protetor de colchão','capa de colchão','manta para sofá','capa para sofá','toalha de banho','toalha de rosto','tapete de box','tapete antiderrapante banheiro','furadeira de impacto','parafusadeira a bateria','serra circular','serra tico-tico','esmerilhadeira','lixadeira orbital','trena digital','nível a laser','multímetro digital','kit ferramentas domésticas','chave inglesa','chave philips','alicate universal','pistola de pintura','mangueira expansível','esguicho para mangueira','aspersor de jardim','irrigador automático','tesoura de poda','aparador de grama','roçadeira elétrica','cortador de grama','vaso autoirrigável','floreira','móveis para varanda','ombrelone','guarda-sol de jardim','capa para churrasqueira','grelha inox']::text[]) AS added(value)
    WHERE btrim(value) <> ''
  ) AS merged
)
WHERE lower(btrim(c.name)) = 'casa & lar';